// Dipanggil tiap ada data sensor dari MQTT (iot/sensor)
const d = msg.payload;
if (typeof d !== 'object' || d === null || typeof d.suhu !== 'number') {
    node.warn('Payload sensor tidak valid');
    return null;
}
d.received = new Date().toISOString();
flow.set('lastSensor', d);   // data terakhir (cepat, di memori)

// Output 1 -> SQLite (history permanen)
const dbMsg = { params: {
    $suhu: d.suhu, $kelembaban: d.kelembaban,
    $timestamp: d.timestamp || null, $received: d.received
}};

// Output 2 -> WebSocket (push ke dashboard, tanpa polling)
const wsMsg = { payload: { type: 'sensor', data: d, status_lampu: flow.get('lampStatus') || 'UNKNOWN' } };

// Output 3 -> Notifikasi bila suhu melewati batas
let alertMsg = null;
const t = flow.get('threshold');
const batas = (typeof t === 'number') ? t : 30;
if (d.suhu > batas) {
    const now = Date.now();
    const last = flow.get('lastAlertTime') || 0;
    if (now - last > 60000) {            // cooldown 60 detik agar tidak spam
        flow.set('lastAlertTime', now);
        const alert = {
            type: 'alert',
            message: 'Suhu ' + d.suhu + '°C melewati batas ' + batas + '°C',
            suhu: d.suhu, threshold: batas, time: d.received
        };
        flow.set('lastAlert', alert);
        alertMsg = { topic: 'iot/alert', payload: alert };
    }
} else {
    flow.set('lastAlertTime', 0);
}
return [dbMsg, wsMsg, alertMsg];

// --- Autentikasi API Key (header X-API-Key) ---
const API_KEY = env.get('API_KEY') || 'iot-kampus-2026';
if (msg.req.headers['x-api-key'] !== API_KEY) {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid atau tidak ada (header X-API-Key)'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return msg;
}
const data = flow.get('lastSensor') || {suhu: null, kelembaban: null, timestamp: null};
const t = flow.get('threshold');
msg.statusCode = 200;
msg.payload = {
    status: 'success',
    data: data,
    status_lampu: flow.get('lampStatus') || 'UNKNOWN',
    threshold: (typeof t === 'number') ? t : 30,
    server_time: new Date().toISOString()
};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

// --- Autentikasi API Key (header X-API-Key) ---
const API_KEY = env.get('API_KEY') || 'iot-kampus-2026';
if (msg.req.headers['x-api-key'] !== API_KEY) {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid atau tidak ada (header X-API-Key)'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null];
}
let n = parseInt(msg.req.query.limit, 10);
if (isNaN(n) || n < 1) n = 50;
if (n > 500) n = 500;
msg.params = {$limit: n};
return [null, msg];

const rows = Array.isArray(msg.payload) ? msg.payload : [];
msg.statusCode = 200;
msg.payload = {status: 'success', count: rows.length, source: 'sqlite', data: rows};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

// --- Autentikasi API Key (header X-API-Key) ---
const API_KEY = env.get('API_KEY') || 'iot-kampus-2026';
if (msg.req.headers['x-api-key'] !== API_KEY) {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid atau tidak ada (header X-API-Key)'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null, null];
}
const body = msg.payload || {};
let device = body.device, action = body.action;
// Kompatibel dengan format materi kuliah: {"perintah": "ON"}
if (!action && body.perintah) { device = device || 'lamp'; action = String(body.perintah); }
if (!device || !action) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'device dan action wajib diisi'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null, null];
}
action = String(action).toLowerCase();
if (action !== 'on' && action !== 'off') {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'action harus on atau off'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null, null];
}
const cmd = {device: device, action: action};
if (device === 'lamp') flow.set('lampStatus', action.toUpperCase());

const mqttMsg = {topic: 'iot/kontrol', payload: cmd};
const wsMsg = {payload: {type: 'lamp', device: device, status: action.toUpperCase()}};

msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Perintah terkirim', sent: cmd};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return [msg, mqttMsg, wsMsg];

// --- Autentikasi API Key (header X-API-Key) ---
const API_KEY = env.get('API_KEY') || 'iot-kampus-2026';
if (msg.req.headers['x-api-key'] !== API_KEY) {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid atau tidak ada (header X-API-Key)'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return msg;
}
const t = flow.get('threshold');
msg.statusCode = 200;
msg.payload = {status: 'success', suhu_max: (typeof t === 'number') ? t : 30};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

// --- Autentikasi API Key (header X-API-Key) ---
const API_KEY = env.get('API_KEY') || 'iot-kampus-2026';
if (msg.req.headers['x-api-key'] !== API_KEY) {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid atau tidak ada (header X-API-Key)'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null];
}
const raw = msg.payload ? msg.payload.suhu_max : undefined;
const v = Number(raw);
if (raw === undefined || raw === null || raw === '' || !isFinite(v) || v < -50 || v > 150) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'suhu_max wajib angka antara -50 dan 150'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null];
}
flow.set('threshold', v);
flow.set('lastAlertTime', 0);    // reset cooldown agar batas baru langsung berlaku

const wsMsg = {payload: {type: 'threshold', suhu_max: v}};
msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Batas suhu diperbarui', suhu_max: v};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return [msg, wsMsg];

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
return msg;
